["void", "AnimalData::walk_data@005d7ea0", "--item", "2900", "--win", "0x180", "--own", "1", "--ptrarg", "0:0x10", "--stub", "0x60cf40:1", "--stub", "slot:0:2", "--stub", "slot:4:1", "--stub", "slot:0x78:1", "--record", "0", "--record", "1", "--record", "2", "--record", "3", "--record-order", "--vtat-also", "p0+0", "--vtat-keep", "0x78:0x60d040", "--wbias", "p0+4:0,1", "--wbias", "m+0x18:0,0,0,0x5a", "--wbias", "m+0x30:0,0,0,0x10000", "--name", "animal_data_walk_data_vt", "--wbias", "m+0x8c:0,-65536", "--wbias", "m+8:0,2,4,1", "--port", "// Object::walk_data(this, walker), then the walker's slot 4 handed the string at the global + 0x22ccc. The kept arm
