["obj", "Armies::find_local_army@006f32e0", "--item=3234", "--win=16", "--own=5", "--ret=eax", "--cell-win=0xc06188:16", "--cell-win=0xc061e8:0x900", "--at=0xcb4bac:4", "--at=0xe3a390:0x60", "--ptrtab=0xc09710:16:0x40", "--ptrtab=0xc0aec0:4:0x20:vt", "--place=0xcae5fc:0:1024", "--place=p18+0x18:0:0x2c0", "--place=p19+0x18:0:0x2c0", "--place=p20+0x18:0:0x2c0", "--place=p21+0x18:0:0x2c0", "--stub=0x6b52e0:2", "--stub=0x46cff0:0", "--stub=0x6f9120:2", "--stub=slot:0xcc:0", "--stub=slot:0xc4:0", "--answers=0:0,1,2", "--answer-range=1:0:150", "--answer-range=2:0:4", "--answers=3:0,1", "--answers=4:0,1", "--wbias=p1..16+8:0,1,2", "--wbias=p1..16+0:0,1,0x100,0x10000", "--wbias=p1..16+0x34:4294967295,0,1", "--wbias=p1..16+0x10:0,1", "--wbias=p1..16+4:0,1,2,3", "--wbias=p1..16+0x38:0,64,128", "--wbias=p1..16+0x3c:0,64,128", "--wbias=p23..26+0x2b8:0,0x40,0x20,0x60", "--wbias=c1+0x820:0,4,0x1000,0x20000,0x1004,0x20004,0x21000,0x21004", "--wbias=c1+0x28:0,16777216,33554432,50331648,67108864", "--wbias=c3+0x50:4294967295,0,1,2,3,4", "--argrange=0:0:0", "--argrange=1:0:16383", "--argrange=2:0:16383", "--argrange=4:-1:3", "--vtat-keep=0xcc:0x46ce80", "--vtat-keep=0xc4:0x46ce60", "--record=1", "--record=2", "--record-edx", "--rows=600", "--port", "{
                // c0 the world cell, c1 `gamec`, c2 `find_dist`, c3 the leaders (player 0); p1..p16 the armies,
                // p23..p26 the units' data; a[5] the region `get_tregion` answers, a[6] `vector_dist`, a[7]
                // `Army::count`, a[8] / a[9] the slot +0xcc / +0xc4 answers, a[10] / a[11] the flags laying
                // `is_supply` / `is_hero`.
                let tre = a[5];
                let who = a[0];
                let mut best = -1i32;
                let mut near = 99_999_999i32;
                c[2][..4].copy_from_slice(&near.to_le_bytes());
                let (mut l1, mut l2) = (Vec::new(), Vec::new());
                let lead = rd(&c[3], 0x50);
                let g = &c[1];
                let diff = if g[0x820] & 4 != 0 {
                    lead
                } else if g[0x821] & 0x10 != 0 && g[0x822] & 2 == 0 {
                    if lead < 0 { i32::from(g[0x2b]) } else { lead }
                } else {
                    i32::from(g[0x2b])
                };
                for k in 0..16usize {
                    let r = &p[1 + k];
                    if i16::from_le_bytes([r[0], r[1]]) == 0 || rd(r, 8) != tre {
                        continue;
                    }
                    let tgt = rd(r, 0x34);
                    if tgt >= 0 && tgt != who {
                        continue;
                    }
                    if !(diff > 2 || r[4] & 1 != 0) {
                        continue;
                    }
                    let dx = a[1].wrapping_sub(rd(r, 0x38)).wrapping_abs();
                    let dy = a[2].wrapping_sub(rd(r, 0x3c)).wrapping_abs();
                    l1.push(format!("{dx},{dy}"));
