                                flags & 0x20 != 0
                            } else {
                                a[9] != 0
                            };
                            if hero {
                                l2.push(format!("p{}+0x0,{},17,54", 1 + k, a[4]));
                                take = a[7] <= 1;
                            } else {
                                take = true;
                            }
