        self.seq(20) != 0
    }
    fn pay_and_cast(&mut self, ty: i32, u: i32, p: i32) {
        self.rec(22, &Self::at(Self::sw(ty)), &[u, p]);
        self.rec(23, &Self::at(Self::sw(ty)), &[u, p, 0, 0]);
