, "0:0,1,1", "--seq", "0:8", "--record", "0", "--stub", "slot:0x3c:0", "--record", "1", "--stub", "slot:0x178:0", "--answers", "2:0,1", "--seq", "2:8", "--record", "2", "--stub", "slot:0xb8:2", "--answers", "3:0,1", "--seq", "3:8", "--record", "3", "--stub", "slot:0x60:2", "--answers", "4:0,1", "--seq", "4:8", "--record", "4", "--stub", "0x633f50:1", "--answers", "5:0,1", "--seq", "5:8", "--record", "5", "--stub", "0x639de0:0", "--answers", "6:0,1", "--seq", "6:8", "--record", "6", "--port", "{
                // `GroupData::count`, arm COUNT_GATHER_POINT (23), inlined: the crate has no `count` of a group's
