                // 1 its slot 0x3c, 2 the build's slot 0x178, 3 its slot 0xb8, 4 the type record's slot 0x60
                // (what the `Build::vftable` arm calls in place of slot 0xb8, 0x211/0x21a/0x1b6/0x1a4/0x208 and
