                let b = &p[20];
                let build = rd(b, 0) == 0xb42174;
                let (bn, btn) = ("p20+0x0", "p21+0x0");
                let is = |ask: &mut dyn FnMut(usize, &str, &str) -> i32, ty: i32| {
