                    if ask(0, &on, "") == 0 {
                        continue;
                    }
                    ask(1, &on, "");
                    // Whether the chain reaches the final pair of tests (any early answer does).
                    let mut reach = (if build {
                        ask(5, btn, &format!(",{}", b[9]))
                    } else {
                        ask(2, bn, "")
                    }) != 0;
                    if !reach {
                        ask(1, &on, "");
                        reach = ask(6, btn, "") != 0;
