                    for ty in [0x211, 0x21a] {
                        if !reach {
                            ask(1, &on, "");
                            reach = is(&mut ask, ty) != 0;
                        }
                    }
                    if !reach {
                        ask(1, &on, "");
                        if is(&mut ask, 0x1b6) == 0 {
                            continue;
                        }
                    }
                    ask(1, &on, "");
                    if is(&mut ask, 0x1a4) != 0 {
                        continue;
                    }
                    ask(1, &on, "");
                    if is(&mut ask, 0x208) == 0 {
                        cnt += 1;
                    }
                }
                for c in &calls {
                    log.push(if c.is_empty() {
                        "-".into()
                    } else {
                        c.join("/")
                    });
                }
                i64::from(cnt)
