["obj", "GroupData::equals_group_const@0070cdf0", "--item", "2346", "--win", "0x8dc", "--own", "1", "--ptrarg", "0:0x8dc", "--stub", "0x70d000:0", "--seq", "0:2", "--answers", "0:0,1", "--record", "0", "--wbias", "m+0x48:0,0x10000,0x100", "--wbias", "p0+0x48:0,0x10000,0x100", "--wbias", "m+0xc:-1..4", "--wbias", "m+0x8cc:0,1,0x10000", "--wbias", "m+0x8d0:0,1,0x10000", "--wbias", "p0+0x8cc:0,1,0x10000", "--wbias", "p0+0x8d0:0,1,0x10000", "--port", "{
                // The owner byte (+0x4a) first; then `get_num_const` (stub 0) of the other group, then
                // of this one, equal, the building flag (+0x49) equal, and the first `num` (+0xc) unit
                // indices of the lists (+0x8cc, shorts) equal.
                let q = &p[0];
                if m[0x4a] != q[0x4a] {
                    log.push("-".into());
                    0
                } else {
                    log.push("p0+0x0/m+0x0".into());
                    let same = a[3] == a[2]
                        && m[0x49] == q[0x49]
                        && (0..rd(m, 0xc).max(0) as usize).all(|i| m[0x8cc + 2 * i..0x8ce + 2 * i] == q[0x8cc + 2 * i..0x8ce + 2 * i]);
                    i64::from(same)
                }
            }"]

["obj", "GroupData::find_leader@0070ccb0", "--item", "2782", "--win", "2508", "--own", "1", "--ptrarg", "0:4", "--ptrarg-null", "0", "--stub", "slot:0x8:0", "--stub", "slot:0xe8:0", "--stub", "slot:0xbc:0", "--stub", "0x72dfc0:3", "--ptrtab", "0xc0ab84+m[0x4a]*0x1c:4:0x20:vt", "--ptrtab", "0xc0aec0+m[0x4a]*0x1c:4:0x20", "--place", "p7+0x18:0:8", "--place", "p8+0x18:0:8", "--place", "p9+0x18:0:8", "--place", "p10+0x18:0:8", "--wbias", "m+12:0,1,2,3,3", "--answers", "0:1,1,1,0", "--answers", "1:1,1,1,0", "--answers", "2:1,1,1,0", "--answer-range", "3:0:20", "--seq", "0:8", "--seq", "1:8", "--seq", "2:4", "--seq", "3:8", "--wbias", "m+2252:0x0,0x10000,0x20000,0x30000,0x1,0x10001,0x20001,0x30001,0x2,0x10002,0x20002,0x30002,0x3,0x10003,0x20003,0x30003", "--wbias", "m+2256:0x0,0x10000,0x20000,0x30000,0x1,0x10001,0x20001,0x30001,0x2,0x10002,0x20002,0x30002,0x3,0x10003,0x20003,0x30003", "--wbias", "m+2260:0x0,0x10000,0x20000,0x30000,0x1,0x10001,0x20001,0x30001,0x2,0x10002,0x20002,0x30002,0x3,0x10003,0x20003,0x30003", "--port", "{
                // Two passes over the list: an object whose slots +8 (stub 0, a[5..]), +0xe8 (stub 1, a[13..]) and,
                // on the first pass only, +0xbc (stub 2, a[21..]) answer is scored by `FormData::type_cat` (stub 3,
                // a[25..]); the lowest score (the first on a tie, the best starting at 0x12) wins. A winner is answered,
                // its list position written through the out-pointer when given; no winner in both passes answers -1.
                let list = |k: usize| i32::from(i16::from_le_bytes([m[0x8cc + 2 * k], m[0x8cd + 2 * k]]));
                let num = rd(m, 12);
                let (mut c0, mut c1, mut c2, mut c3) = (0usize, 0usize, 0usize, 0usize);
                let (mut best, mut best_pos, mut best_cat) = (-1i32, 0i32, 0x12i32);
                let mut res = -1i64;
                'pass: for pass in 0..2 {
                    for pos in 0..usize::try_from(num.max(0)).expect("a count") {
                        let i = list(pos);
                        let r0 = a[5 + c0];
                        c0 += 1;
                        if r0 == 0 {
