                        let limit0 = a[4 + c0];
                        c0 += 1;
                        let mut b5 = 0i32;
                        let mut c1v = 0i32;
                        if limit0 >= 1 {
                            let mut limit = limit0;
                            let mut i = 0usize;
                            while (i as i32) < limit {
                                let idx = list(i);
                                if a[14 + c2] != 0 {
