["obj", "Unit::update_armor@006054c0", "--port", "{
                // The climb: a unit whose slot +0xe8 is `is_captain` (a[4] = 1) is a captain when the high bit
                // of the short at +0x8e is set; otherwise the stub answers a[3]. A non-captain asks the object
                // `p[1 + idx]` (idx = that short) for its parent, `p[8 + idx]`. Unit 0 is `m`, unit 1 + k is `p[8 + k]`.
                let base = a[4] != 0;
                let s16 = |w: &[u8], o: usize| i16::from_le_bytes([w[o], w[o + 1]]);
                let mut cur: Option<usize> = None;
                loop {
                    let w: &[u8] = match cur {
                        None => &m[..],
                        Some(k) => &p[8 + k][..],
                    };
                    let cap = if base { u32::from(s16(w, 0x8e) as u16 >> 15) } else { a[3] as u32 };
                    if cap != 0 {
                        break;
                    }
                    cur = Some(usize::try_from(s16(w, 0x8e)).expect("index"));
                }
                let (w, ty): (Vec<u8>, i32) = match cur {
                    None => (m.to_vec(), rd(&p[24], 4)),
                    Some(k) => (p[8 + k].clone(), rd(&p[25 + k], 4)),
                };
                let b = usize::from(w[9]);
                let mut armor = a[2] as i16;
                if ty == 0x32 || ty == 0x33 {
                    let base_off = b * 0x6eec;
                    if c[2][base_off + 0x6da7] & 0x80 != 0 || c[2][base_off + 0x6dcf] & 0x80 != 0 {
                        armor = armor.wrapping_add(rd(&c[1], 0x960) as i16);
                    }
                }
                let ab = armor.to_le_bytes();
                match cur {
                    None => m[0x9c..0x9e].copy_from_slice(&ab),
                    Some(k) => p[8 + k][0x9c..0x9e].copy_from_slice(&ab),
                }
                let mut idx = s16(&w, 0x90);
                while idx >= 0 {
                    let rec = &mut p[(if b == 0 { 15 } else { 20 }) + idx as usize];
                    rec[0x9c..0x9e].copy_from_slice(&ab);
                    idx = s16(rec, 0x90);
                }
                i64::from(armor)
            }", "--item", "3058", "--win", "0xa0", "--own", "0", "--rows", "800", "--cell-win", "0xc0618c:0x60", "--cell-win", "0xc061f0:0x980", "--at", "0xe3a390:56792", "--stub", "slot:0xa8:0", "--stub", "slot:0xe8:0", "--stub", "0x647db0:0", "--slotbase", "0xe8:0x46ceb0", "--seq", "1:1:1", "--ptrtab", "c0+0x14:6:0x10:vt", "--alias", "c0+0x30:p0!", "--ptrtab", "m+0x60:6:0xa0:vt", "--ptrtab", "0xc0aec0:4:0xa0", "--ptrtab", "0xc0aedc:4:0xa0", "--answer-by", "0:1:8:6:0x8e", "--place", "m+0x18:0:8", "--place", "p8+0x18:0:8", "--place", "p9+0x18:0:8", "--place", "p10+0x18:0:8", "--place", "p11+0x18:0:8", "--place", "p12+0x18:0:8", "--place", "p13+0x18:0:8", "--wbias", "m+8:0,0x100", "--wbias", "p8..13+8:0,0x100", "--wbias", "m+0x8c:0,0x10000,0x20000,0x30000,0x50000,0xffff0000,0x80000000", "--wbias", "m+0x90:0xffff,0,1,2,3,0x10003", "--wbias", "p8..13+0x90:0xffff,0,1,2,3", "--link", "p15..18+0x90:2:>", "--link", "p20..23+0x90:2:>", "--wbias", "p24..30+4:0x32,0x33,0x31,0x34,5"]

